#include <cstdio>
#include <cstring>
#include <algorithm>
using namespace std;

char s[101];
int n;

int dp(int i, int j) {
    if (i >= n || j >= n || s[i] != s[j]) return 0;
    return 1 + dp(i + 1, j + 1);
}

int main() {
    if (!fgets(s, sizeof(s), stdin)) return 0;
    s[strcspn(s, "\r\n")] = '\0';
    n = strlen(s);

    int m = 0;
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)
            m = max(m, dp(i, j));

    printf("%d\n", m);
    return 0;
}

